import{_ as a,o as t,c as i,al as n}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"X-Plane Simulation","description":"","frontmatter":{},"headers":[],"relativePath":"uk/sim_xplane/index.md","filePath":"uk/sim_xplane/index.md"}'),s={name:"uk/sim_xplane/index.md"};function l(r,e,o,d,p,h){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="x-plane-simulation" tabindex="-1">X-Plane Simulation <a class="header-anchor" href="#x-plane-simulation" aria-label="Permalink to &quot;X-Plane Simulation&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This simulator is <a href="./../simulation/community_supported_simulators">community supported and maintained</a>. It may or may not work with current versions of PX4 and may be removed in future releases. Дивіться <a href="./../dev_setup/dev_env">Встановлення інструментарію</a> для інформації про середовища та інструменти, що підтримуються основною командою розробників.</p></div><p><a href="https://www.x-plane.com/" target="_blank" rel="noreferrer">X-Plane</a> can be used with PX4 for <a href="./../simulation/#sitl-simulation-environment">Software-In-The-Loop (SITL)</a> simulation through the community-supported <a href="https://github.com/alireza787b/px4xplane" target="_blank" rel="noreferrer">px4xplane</a> bridge plugin. PX4 runs as the flight controller, while X-Plane provides the vehicle dynamics, visual scene, and simulated sensor inputs. The px4xplane bridge is an X-Plane plugin: it runs inside X-Plane, accepts PX4&#39;s simulator MAVLink connection, publishes simulated sensors to PX4, and writes PX4 actuator outputs to X-Plane datarefs.</p><h2 id="підтримувані-транспортні-засоби" tabindex="-1">Підтримувані транспортні засоби <a class="header-anchor" href="#підтримувані-транспортні-засоби" aria-label="Permalink to &quot;Підтримувані транспортні засоби&quot;">​</a></h2><p>PX4 includes X-Plane SITL airframes for the following vehicles:</p><table tabindex="0"><thead><tr><th>Транспортний засіб</th><th>Тип</th><th>PX4 target</th></tr></thead><tbody><tr><td>Cessna 172</td><td>Plane</td><td><code>make px4_sitl_default xplane_cessna172</code></td></tr><tr><td>TB2</td><td>Plane</td><td><code>make px4_sitl_default xplane_tb2</code></td></tr><tr><td>Ehang 184</td><td>Мультикоптер</td><td><code>make px4_sitl_default xplane_ehang184</code></td></tr><tr><td>Alia-250</td><td>VTOL quadplane</td><td><code>make px4_sitl_default xplane_alia250</code></td></tr><tr><td>QuadTailsitter</td><td>VTOL tailsitter</td><td><code>make px4_sitl_default xplane_qtailsitter</code></td></tr></tbody></table><p>The matching X-Plane aircraft files and bridge configuration are distributed by the px4xplane project. Additional X-Plane aircraft or vehicle models can also be integrated when PX4 has a matching SITL-capable control path and px4xplane can map the required actuator outputs to writable X-Plane datarefs.</p><h2 id="встановлення" tabindex="-1">Встановлення <a class="header-anchor" href="#встановлення" aria-label="Permalink to &quot;Встановлення&quot;">​</a></h2><ol><li><p>Install the <a href="./../dev_setup/dev_env">PX4 development environment</a> on the machine, container, or WSL2 environment that will run PX4 SITL.</p></li><li><p>Install X-Plane 11 or X-Plane 12.</p></li><li><p>Download the latest OS-specific px4xplane release package from the <a href="https://github.com/alireza787b/px4xplane/releases" target="_blank" rel="noreferrer">px4xplane releases page</a>.</p></li><li><p>The release package is an archive, not an installer. Extract it and copy the complete <code>px4xplane</code> plugin folder into:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">X-Plane/Resources/plugins/px4xplane</span></span></code></pre></div></li><li><p>Copy the matching X-Plane aircraft folders from the same extracted package into an X-Plane aircraft directory. Keep the packaged <code>64/config.ini</code> with the <code>px4xplane</code> plugin unless the release notes say otherwise.</p></li></ol><p>The <a href="https://github.com/alireza787b/px4xplane/blob/master/docs/BUILD.md#installation" target="_blank" rel="noreferrer">px4xplane build and installation guide</a> has more detail on the plugin folder layout.</p><h2 id="network-setup" tabindex="-1">Network Setup <a class="header-anchor" href="#network-setup" aria-label="Permalink to &quot;Network Setup&quot;">​</a></h2><p>PX4 connects to the X-Plane bridge on TCP port <code>4560</code>. The default host is <code>localhost</code>, which is suitable when PX4 and X-Plane run on the same Linux or macOS machine.</p><p>For Windows, the usual setup is X-Plane running natively on Windows and PX4 running in WSL2. In that case, set <code>PX4_SIM_HOSTNAME</code> in the WSL2 shell to the Windows host IP before starting PX4. This variable is set on the PX4/SITL side and points to the host where X-Plane and the px4xplane plugin are running:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_SIM_HOSTNAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/default/ {print $3; exit}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Then start the desired PX4 target from the same shell. If PX4 runs in Docker or on another computer, set <code>PX4_SIM_HOSTNAME</code> to the reachable IP address or hostname of the X-Plane machine instead. Make sure inbound TCP port <code>4560</code> is allowed by the firewall on the X-Plane host.</p><h2 id="запуск-sitl" tabindex="-1">Запуск SITL <a class="header-anchor" href="#запуск-sitl" aria-label="Permalink to &quot;Запуск SITL&quot;">​</a></h2><ol><li><p>Start X-Plane and load the aircraft that matches the PX4 target.</p></li><li><p>Confirm the px4xplane plugin is loaded in the X-Plane plugin menu.</p></li><li><p>Start PX4 SITL. Наприклад:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PX4-Autopilot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xplane_alia250</span></span></code></pre></div></li><li><p>Connect QGroundControl to PX4 as usual.</p></li></ol><p>PX4 prints <code>Simulator connected on TCP port 4560</code> when the bridge is connected.</p><h2 id="custom-aircraft" tabindex="-1">Custom Aircraft <a class="header-anchor" href="#custom-aircraft" aria-label="Permalink to &quot;Custom Aircraft&quot;">​</a></h2><p>To add another X-Plane aircraft:</p><ol><li>Create a PX4 airframe file in <code>ROMFS/px4fmu_common/init.d-posix/airframes</code>.</li><li>Add a matching SITL target in <code>src/modules/simulation/simulator_mavlink/sitl_targets_xplane.cmake</code>.</li><li>Configure the px4xplane bridge to map PX4 actuator outputs to the aircraft datarefs.</li><li>Tune the PX4 parameters from ULog data and X-Plane truth logs.</li></ol><p>See the <a href="https://github.com/alireza787b/px4xplane/blob/master/docs/custom-airframe-config.md" target="_blank" rel="noreferrer">px4xplane custom airframe guide</a> for bridge configuration details. For X-Plane-side aircraft design and dataref mapping, see the official <a href="https://developer.x-plane.com/manuals/planemaker/" target="_blank" rel="noreferrer">Plane Maker manual</a> and <a href="https://developer.x-plane.com/datarefs/" target="_blank" rel="noreferrer">X-Plane datarefs reference</a>.</p><h2 id="усунення-проблем" tabindex="-1">Усунення проблем <a class="header-anchor" href="#усунення-проблем" aria-label="Permalink to &quot;Усунення проблем&quot;">​</a></h2><p>If PX4 waits for the simulator, verify that X-Plane is running, the px4xplane plugin is loaded, <code>PX4_SIM_HOSTNAME</code> points to the X-Plane host, and TCP port <code>4560</code> is not blocked.</p><p>If the aircraft loads but does not respond correctly, verify that the X-Plane aircraft, PX4 target, and px4xplane configuration all refer to the same vehicle.</p><p>If estimator warnings appear, keep the simulator frame rate stable, check that the intended airframe parameters were loaded, and inspect the ULog sensor and estimator topics before changing bridge or airframe parameters.</p>`,26)])])}const m=a(s,[["render",l]]);export{u as __pageData,m as default};
